sql.where:
rows.use_yn=#{useYn}
AND rows.status=#{status}AND rows.status!='퇴사'
AND rows.emp_se_cd=#{empType}
AND (rows.main_job_cd=#{job} OR EXISTS(SELECT 1 FROM mst.dev_sub_job s WHERE s.dev_id=rows.dev_id AND s.job_cd=#{job}))
AND (position(lower(#{q}) in lower(rows.dev_nm))>0 OR position(lower(#{q}) in lower(rows.mng_no))>0)
